import{_ as l,a0 as d,w as o,s as r,ao as p,I as n,a1 as i,A as t,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何在 CentOS、RHEL 和 Fedora 上安裝 DHCP 服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS、RHEL 和 Fedora 上安裝 DHCP 服務 | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS、RHEL 和 Fedora 上安裝 DHCP 服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS、RHEL 和 Fedora 上安裝 DHCP 服務 | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170321 How to Install a DHCP Server in CentOS RHEL and Fedora","title":"如何在 CentOS、RHEL 和 Fedora 上安裝 DHCP 服務","tag":"201704","desc":""},"relativePath":"201704/20170321 How to Install a DHCP Server in CentOS RHEL and Fedora.md","filePath":"[post].md"}'),h={name:"201704/20170321 How to Install a DHCP Server in CentOS RHEL and Fedora.md"};function c(g,s,C,u,k,b){const e=d("Link");return o(),r("div",null,[s[16]||(s[16]=p(`<h1 id="如何在-centos、rhel-和-fedora-上安裝-dhcp-服務" tabindex="-1">如何在 CentOS、RHEL 和 Fedora 上安裝 DHCP 服務 <a class="header-anchor" href="#如何在-centos、rhel-和-fedora-上安裝-dhcp-服務" aria-label="Permalink to “如何在 CentOS、RHEL 和 Fedora 上安裝 DHCP 服務”">​</a></h1><p>DHCP（Dynamic Host Configuration Protocol）是一個網絡協議，它使得服務器能從預定義的 IP 池中為網絡中的客户端節點自動分配 IP 地址並提供其它相關的網絡配置參數。</p><p>這意味着每次客户端節點啓動（連接到網絡）的時候，它都會獲得一個和從不改變的“靜態” IP 地址相反的“動態” IP 地址。DHCP 服務器給 DHCP 客户端分配 IP 地址稱為“租約”，租約時間隨客户端需要的連接時間或 DHCP 的配置而異。</p><p>在這篇指南中，我們會介紹如何在 CentOS/RHEL 和 Fedora 發行版中安裝和配置 DHCP 服務。</p><h3 id="設置測試環境" tabindex="-1">設置測試環境 <a class="header-anchor" href="#設置測試環境" aria-label="Permalink to “設置測試環境”">​</a></h3><p>本次安裝中我們使用如下的測試環境：</p><ul><li>DHCP 服務器 - CentOS 7</li><li>DHCP 客户端 - Fedora 25 和 Ubuntu 16.04</li></ul><h3 id="dhcp-如何工作" tabindex="-1">DHCP 如何工作？ <a class="header-anchor" href="#dhcp-如何工作" aria-label="Permalink to “DHCP 如何工作？”">​</a></h3><p>在進入下一步之前，讓我們首先了解一下 DHCP 的工作流程：</p><ul><li>當已連接到網絡的客户端計算機（配置為使用 DHCP）啓動時，它會發送一個 <code>DHCPDISCOVER</code> 消息到 DHCP 服務器。</li><li>當 DHCP 服務器接收到 <code>DHCPDISCOVER</code> 請求消息時，它會回覆一個 <code>DHCPOFFER</code> 消息。</li><li>客户端收到 <code>DHCPOFFER</code> 消息後，它再發送給服務器一個 <code>DHCPREQUEST</code> 消息，表示客户端已準備好獲取 <code>DHCPOFFER</code> 消息中提供的網絡配置。</li><li>最後，DHCP 服務器收到客户端的 <code>DHCPREQUEST</code> 消息，並回復 <code>DHCPACK</code> 消息，表示允許客户端使用分配給它的 IP 地址。</li></ul><h3 id="第一步-在-centos-上安裝-dhcp-服務" tabindex="-1">第一步：在 CentOS 上安裝 DHCP 服務 <a class="header-anchor" href="#第一步-在-centos-上安裝-dhcp-服務" aria-label="Permalink to “第一步：在 CentOS 上安裝 DHCP 服務”">​</a></h3><p>1、安裝 DHCP 服務非常簡單，只需要運行下面的命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yum -y install dhcp</span></span></code></pre></div><p>重要：假如系統中有多個網卡，但你想只在其中一個網卡上啓用 DHCP 服務，可以按照下面的步驟在該網卡上啓用 DHCP 服務。</p><p>2、 打開文件 <code>/etc/sysconfig/dhcpd</code>，將指定網卡的名稱添加到 <code>DHCPDARGS</code> 列表，假如網卡名稱為 <code>eth0</code>，則添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DHCPDARGS=eth0</span></span></code></pre></div><p>保存文件並退出 。</p><h3 id="第二步-在-centos-上配置-dhcp-服務" tabindex="-1">第二步：在 CentOS 上配置 DHCP 服務 <a class="header-anchor" href="#第二步-在-centos-上配置-dhcp-服務" aria-label="Permalink to “第二步：在 CentOS 上配置 DHCP 服務”">​</a></h3><p>3、 對於初學者來説，配置 DHCP 服務的第一步是創建 <code>dhcpd.conf</code> 配置文件，DHCP 主要配置文件一般是 <code>/etc/dhcp/dhcpd.conf</code>（默認情況下該文件為空），該文件保存了發送給客户端的所有網絡信息。</p><p>但是，有一個樣例配置文件 <code>/usr/share/doc/dhcp*/dhcpd.conf.sample</code>，這是配置 DHCP 服務的良好開始。</p><p>DHCP 配置文件中定義了兩種類型的語句：</p><ul><li>參數 - 説明如何執行任務、是否執行任務、或者給 DHCP 客户端發送什麼網絡配置選項。</li><li>聲明 - 指定網絡拓撲、定義客户端、提供客户端地址、或將一組參數應用於一組聲明。</li></ul><p>因此，首先複製示例配置文件為主配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /usr/share/doc/dhcp-4.2.5/dhcpd.conf.example /etc/dhcp/dhcpd.conf</span></span></code></pre></div><p>4、 然後，打開主配置文件並定義你的 DHCP 服務選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/dhcp/dhcpd.conf</span></span></code></pre></div><p>首先在文件開頭設置以下應用於全部子網的全局參數（注意要使用你實際場景中的值）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>option domain-name &quot;tecmint.lan&quot;;</span></span>
<span class="line"><span>option domain-name-servers ns1.tecmint.lan, ns2.tecmint.lan;</span></span>
<span class="line"><span>default-lease-time 3600; </span></span>
<span class="line"><span>max-lease-time 7200;</span></span>
<span class="line"><span>authoritative;</span></span></code></pre></div><p>5、 然後，定義一個子網；在這個事例中，我們會為 <code>192.168.56.0/24</code> 局域網配置 DHCP（注意使用你實際場景中的值）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>subnet 192.168.56.0 netmask 255.255.255.0 {</span></span>
<span class="line"><span>option routers                  192.168.56.1;</span></span>
<span class="line"><span>option subnet-mask              255.255.255.0;</span></span>
<span class="line"><span>option domain-search            &quot;tecmint.lan&quot;;</span></span>
<span class="line"><span>option domain-name-servers      192.168.56.1;</span></span>
<span class="line"><span>range   192.168.56.10   192.168.56.100;</span></span>
<span class="line"><span>range   192.168.56.120  192.168.56.200;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="第三步-為-dhcp-客户端分配靜態-ip" tabindex="-1">第三步：為 DHCP 客户端分配靜態 IP <a class="header-anchor" href="#第三步-為-dhcp-客户端分配靜態-ip" aria-label="Permalink to “第三步：為 DHCP 客户端分配靜態 IP”">​</a></h3><p>只需要在 <code>/etc/dhcp/dhcpd.conf</code> 文件中定義下面的部分，其中你必須顯式指定它的 MAC 地址和打算分配的 IP，你就可以為網絡中指定的客户端計算機分配一個靜態 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host ubuntu-node {</span></span>
<span class="line"><span>hardware  ethernet 00:f0:m4:6y:89:0g;</span></span>
<span class="line"><span>fixed-address 192.168.56.105;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>host fedora-node {</span></span>
<span class="line"><span>hardware  ethernet 00:4g:8h:13:8h:3a;</span></span>
<span class="line"><span>fixed-address 192.168.56.110;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存文件並關閉。</p><p>注意：你可以使用下面的命令找到 Linux 的 MAC 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ifconfig -a eth0 | grep HWaddr</span></span></code></pre></div><p>6、 現在，使用下面的命令啓動 DHCP 服務，並使在下次系統啓動時自動啓動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------- On CentOS/RHEL 7 ---------- </span></span>
<span class="line"><span>$ systemctl start dhcpd</span></span>
<span class="line"><span>$ systemctl enable dhcpd</span></span>
<span class="line"><span>---------- On CentOS/RHEL 6 ----------</span></span>
<span class="line"><span>$ service dhcpd start</span></span>
<span class="line"><span>$ chkconfig dhcpd on</span></span></code></pre></div><p>7、 另外，別忘了使用下面的命令允許 DHCP 服務通過防火牆（DHCPD 守護進程通過 UDP 監聽67號端口）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------- On CentOS/RHEL 7 ----------</span></span>
<span class="line"><span>$ firewall-cmd --add-service=dhcp --permanent </span></span>
<span class="line"><span>$ firewall-cmd --reload </span></span>
<span class="line"><span>---------- On CentOS/RHEL 6 ----------</span></span>
<span class="line"><span>$ iptables -A INPUT -p tcp -m state --state NEW --dport 67 -j ACCEPT</span></span>
<span class="line"><span>$ service iptables save</span></span></code></pre></div><h3 id="第四步-配置-dhcp-客户端" tabindex="-1">第四步：配置 DHCP 客户端 <a class="header-anchor" href="#第四步-配置-dhcp-客户端" aria-label="Permalink to “第四步：配置 DHCP 客户端”">​</a></h3><p>8、 現在，你可以為網絡中的客户端配置自動從 DHCP 服務器中獲取 IP 地址。登錄到客户端機器並按照下面的方式修改以太網接口的配置文件（注意網卡的名稱和編號）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/sysconfig/network-scripts/ifcfg-eth0</span></span></code></pre></div><p>添加下面的選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DEVICE=eth0</span></span>
<span class="line"><span>BOOTPROTO=dhcp</span></span>
<span class="line"><span>TYPE=Ethernet</span></span>
<span class="line"><span>ONBOOT=yes</span></span></code></pre></div><p>保存文件並退出。</p><p>9、 你也可以在桌面服務器中按照下面的截圖（Ubuntu 16.04桌面版）通過 GUI 設置 <code>Method</code> 為 <code>Automatic (DHCP)</code>。</p>`,47)),n("p",null,[i(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/03/Set-DHCP-in-Client-Network.png"},{default:t(()=>[...s[0]||(s[0]=[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/03/Set-DHCP-in-Client-Network.png",alt:"Set DHCP in Client Network"},null,-1)])]),_:1})]),s[17]||(s[17]=p(`<p><em>在客户端網絡中設置 DHCP</em></p><p>10、 按照下面的命令重啓網絡服務（你也可以通過重啓系統）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>---------- On CentOS/RHEL 7 ----------</span></span>
<span class="line"><span>$ systemctl restart network</span></span>
<span class="line"><span>---------- On CentOS/RHEL 6 ----------</span></span>
<span class="line"><span>$ service network restart</span></span></code></pre></div><p>到了這裏，如果所有設置都是正確的，你的客户端就應該能自動從 DHCP 服務器中獲取 IP 地址。</p><p>你也可以閲讀：</p>`,5)),n("ol",null,[n("li",null,[i(e,{href:"http://www.tecmint.com/install-and-configure-multihomed-isc-dhcp-server-on-debian-linux/"},{default:t(()=>[...s[1]||(s[1]=[a("如何在 Debian Linux 中安裝和配置 Multihomed ISC DHCP 服務",-1)])]),_:1})]),n("li",null,[i(e,{href:"http://www.tecmint.com/ip-command-examples/"},{default:t(()=>[...s[2]||(s[2]=[a("配置網絡的10個有用的 “IP” 命令",-1)])]),_:1})])]),s[18]||(s[18]=n("p",null,"在這篇文章中我們為你展示瞭如何在 RHEL/CentOS 中安裝 DHCP 服務。在下面的評論框中給我們反饋吧。在接下來的文章中，我們還會為你展示如何在 Debian/Ubuntu 中安裝 DHCP 服務。和 TecMint 保持聯繫。",-1)),s[19]||(s[19]=n("hr",null,null,-1)),s[20]||(s[20]=n("p",null,"作者簡介：",-1)),s[21]||(s[21]=n("p",null,"Aaron Kili 是一個 Linux 和 F.O.S.S 的愛好者，即將推出的 Linux SysAdmin 網絡開發人員，目前也是 TecMint 的內容創作者，他喜歡和電腦一起工作，並且堅信共享知識。",-1)),s[22]||(s[22]=n("hr",null,null,-1)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),i(e,{href:"http://www.tecmint.com/install-dhcp-server-in-centos-rhel-fedora/"},{default:t(()=>[...s[3]||(s[3]=[a("http://www.tecmint.com/install-dhcp-server-in-centos-rhel-fedora/",-1)])]),_:1})]),n("p",null,[s[8]||(s[8]=a("作者：",-1)),i(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:t(()=>[...s[5]||(s[5]=[a("Aaron Kili",-1)])]),_:1}),s[9]||(s[9]=a(" 譯者：",-1)),i(e,{href:"https://github.com/ictlyh"},{default:t(()=>[...s[6]||(s[6]=[a("ictlyh",-1)])]),_:1}),s[10]||(s[10]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[11]||(s[11]=[a("LCTT",-1)])]),_:1}),s[14]||(s[14]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[12]||(s[12]=[a("Linux中國",-1)])]),_:1}),s[15]||(s[15]=a(" 榮譽推出",-1))])])}const H=l(h,[["render",c]]);export{m as __pageData,H as default};
